#!/bin/bash
# Task 187-docs-toolchain -- meshsim sim/, the docs session, for the owner: is the RISC-V toolchain the owner installed on the
# runner (apt: gcc-riscv64-unknown-elf, picolibc-riscv64-unknown-elf, patch) the one v1.35's firmware is built with, and
# does it reproduce every committed image? It records the toolchain's versions, then runs fw/build.sh --check on meshsim
# main 5694f93a's firmware sources: every image built must equal its committed copy byte for byte (the fixtures'
# folders tests/golden/images, tests/golden-m2/images, tests/m3-images, and fw/images). fw/build.sh is what
# run_tests.sh's pending steps sw-build and sort-build are in v1.35; a PASS here says they can go live on the runner.
# Expected: riscv64-unknown-elf-gcc 13.2.0 (Ubuntu 24.04's 13.2.0-11ubuntu1+12), and no image differing.
# From an embedded kit (sim/fw, the three fixture image folders, sim/tools/machine.sh). Not timing. Writes only
# results/187-docs-toolchain/. Scratch in /tmp, removed first and at the end. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/187-docs-toolchain; mkdir -p "$RES"
W=/tmp/docs-187; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "69b3c6b0e53e0978367b17c373012a48ffba9658911a1bf6df19c761440ef3a7" ] || { echo "kit sha256 mismatch (want 69b3c6b0e53e0978367b17c373012a48ffba9658911a1bf6df19c761440ef3a7)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KS=$W/kit/sim
FAIL=0
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
echo "kit: $(cat $W/kit/VERSION); host $(hostname)"
bash "$KS/tools/machine.sh" record "$RES/machine.txt" > /dev/null 2>&1; cat "$RES/machine.txt" 2>/dev/null

# 1. the toolchain, as installed
{
  echo "== which"; for t in riscv64-unknown-elf-gcc riscv64-unknown-elf-ld riscv64-unknown-elf-objcopy patch; do printf '%s: ' $t; command -v $t || echo MISSING; done
  echo "== riscv64-unknown-elf-gcc --version"; riscv64-unknown-elf-gcc --version 2>&1 | head -1
  echo "== riscv64-unknown-elf-ld --version"; riscv64-unknown-elf-ld --version 2>&1 | head -1
  echo "== packages"; dpkg-query -W -f='${Package} ${Version} ${Status}\n' gcc-riscv64-unknown-elf binutils-riscv64-unknown-elf picolibc-riscv64-unknown-elf patch 2>&1
  echo "== os"; (. /etc/os-release 2>/dev/null; echo "$PRETTY_NAME")
} > "$RES/toolchain.txt" 2>&1
cat "$RES/toolchain.txt"
command -v riscv64-unknown-elf-gcc > /dev/null && command -v patch > /dev/null && verdict toolchain-present PASS || verdict toolchain-present FAIL
riscv64-unknown-elf-gcc --version 2>/dev/null | head -1 | grep -q '13\.2\.0' && verdict gcc-13.2.0 PASS || verdict gcc-13.2.0 FAIL

# 2. every firmware image against its committed copy
cd "$KS"
t0=$(date +%s); OUT="$W/out" bash fw/build.sh --check > "$RES/build_check.log" 2>&1; rc=$?
echo "fw/build.sh --check: exit $rc in $(( $(date +%s) - t0 )) s"
tail -40 "$RES/build_check.log"
[ $rc = 0 ] && ! grep -q -E 'DIFFERS|MISSING|missing' "$RES/build_check.log" && verdict images-identical PASS || verdict images-identical FAIL
(cd "$W/out" 2>/dev/null && find . -type f | LC_ALL=C sort | xargs sha256sum) > "$RES/built.sha256" 2>/dev/null
echo "images built: $(wc -l < "$RES/built.sha256")"

echo; cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo DONE; exit 0; } || { echo FAILED; exit 1; }
